// Un modelo mínimo del bucle de eventos de Node: no es Node, solo la forma de sus fases.
const RETRASO_ARRANQUE = 0;      // ms que tarda el programa en llegar al bucle (probá 0 y 2)

let ahora = 0;                   // reloj simulado, en ms
const timers = [], listosIO = [], inmediatos = [], ticks = [], micro = [];
const log = (t) => console.log(String(ahora).padStart(2) + ' ms  ' + t);

// la API que ve tu código
const setTimeoutSim = (f, ms) => timers.push({ cuando: ahora + Math.max(1, ms), f });
const setImmediateSim = (f) => inmediatos.push(f);
const nextTickSim = (f) => ticks.push(f);
const promesaSim = (f) => micro.push(f);
const leerArchivoSim = (f) => listosIO.push({ cuando: ahora + 3, f });   // «el disco tarda 3 ms»

// entre un callback y el siguiente se vacían primero nextTick y después las microtareas
function vaciarColas() {
  while (ticks.length || micro.length) {
    while (ticks.length) ticks.shift()();
    while (micro.length) micro.shift()();
  }
}
function correr(f) { f(); vaciarColas(); }

// --- tu programa ---
log('código sincrónico: inicio');
setTimeoutSim(() => log('timers: setTimeout 0'), 0);
setImmediateSim(() => log('check: setImmediate'));
leerArchivoSim(() => {
  log('poll: terminó la lectura del archivo');
  setTimeoutSim(() => log('timers: setTimeout 0 pedido desde la lectura'), 0);
  setImmediateSim(() => log('check: setImmediate pedido desde la lectura'));
});
promesaSim(() => log('microtarea: promesa'));
nextTickSim(() => log('nextTick'));
log('código sincrónico: fin');
vaciarColas();

// --- el bucle ---
ahora += RETRASO_ARRANQUE;
while (timers.length || listosIO.length || inmediatos.length) {
  // 1. timers: los vencidos
  timers.sort((a, b) => a.cuando - b.cuando);
  while (timers.length && timers[0].cuando <= ahora) correr(timers.shift().f);
  // 2. poll: la E/S que ya terminó
  for (const e of listosIO.filter((e) => e.cuando <= ahora)) { listosIO.splice(listosIO.indexOf(e), 1); correr(e.f); }
  // 3. check: los setImmediate de esta vuelta
  for (const f of inmediatos.splice(0)) correr(f);
  ahora += 1;                    // pasa el tiempo
}

