const fs = require('node:fs');
const crypto = require('node:crypto');
const { pipeline } = require('node:stream/promises');
const t0 = performance.now();
const hash = crypto.createHash('sha256');
let trozos = 0, primero = 0;
const lectura = fs.createReadStream(process.argv[2]);
lectura.on('data', (t) => { if (!trozos++) primero = t.length; });
pipeline(lectura, hash).then(() => {
  console.log('modo: stream');
  console.log('sha256:', hash.digest('hex').slice(0, 16) + '…');
  console.log(`trozos: ${trozos} de ${primero} bytes`);
  console.log('tiempo:', Math.round(performance.now() - t0), 'ms');
  console.log('memoria máxima (RSS):', Math.round(process.resourceUsage().maxRSS / 1024), 'MiB');
});

const { Writable } = require('node:stream');
const { once } = require('node:events');

const MODO = process.argv[2];                 // 'ignora' o 'respeta'
const TROZOS = 3200;                          // 3200 trozos de 64 KiB = 200 MiB

// un destino lento: tarda 1 ms en «procesar» cada trozo (como una red o un disco lento)
const destino = new Writable({
  write(_t, _enc, listo) { setTimeout(listo, 1); },
});

let maxEnCola = 0, dijoBasta = 0;
(async () => {
  const t0 = performance.now();
  for (let i = 0; i < TROZOS; i++) {
    const cabeEnElBuffer = destino.write(Buffer.alloc(64 * 1024, 'x'));   // un trozo nuevo por vuelta
    maxEnCola = Math.max(maxEnCola, destino.writableLength);
    if (!cabeEnElBuffer) {
      dijoBasta++;
      if (MODO === 'respeta') await once(destino, 'drain');   // esperar a que se vacíe
    }
  }
  destino.end();
  await once(destino, 'finish');
  console.log(`modo ${MODO}: write() devolvió false ${dijoBasta} veces`);
  console.log(`  máximo acumulado en el buffer del stream: ${(maxEnCola / 1024 / 1024).toFixed(1)} MiB (límite de aviso: ${destino.writableHighWaterMark / 1024} KiB)`);
  console.log(`  memoria máxima (RSS): ${Math.round(process.resourceUsage().maxRSS / 1024)} MiB, tiempo total ${Math.round(performance.now() - t0)} ms`);
})();

// fib(42) recursivo: ~2 segundos de CPU pura en esta VM
function fib(n) { return n < 2 ? n : fib(n - 1) + fib(n - 2); }
module.exports = { fib };

const http = require('node:http');
const { Worker } = require('node:worker_threads');
const { monitorEventLoopDelay } = require('node:perf_hooks');
const { fib } = require('./calculo.js');

const PUERTO = Number(process.env.PUERTO || 19084);
const retraso = monitorEventLoopDelay({ resolution: 10 });
retraso.enable();

const json = (res, cuerpo) => {
  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ pid: process.pid, ...cuerpo }));
};

http.createServer((req, res) => {
  const t0 = performance.now();
  if (req.url === '/rapida') return json(res, { ruta: 'rapida' });

  if (req.url === '/lenta') {                         // cálculo en el hilo principal
    return json(res, { ruta: 'lenta', resultado: fib(42), ms: Math.round(performance.now() - t0) });
  }
  if (req.url === '/espera') {                        // lenta, pero esperando (no calcula)
    return setTimeout(() => json(res, { ruta: 'espera', ms: Math.round(performance.now() - t0) }), 2000);
  }
  if (req.url === '/worker') {                        // el mismo cálculo, en otro hilo
    const w = new Worker(require.resolve('./trabajador.js'), { workerData: 42 });
    return w.once('message', (r) => json(res, { ruta: 'worker', resultado: r, ms: Math.round(performance.now() - t0) }));
  }
  if (req.url === '/retraso') {                       // cuánto se atrasó el bucle de eventos
    const r = { maxMs: +(retraso.max / 1e6).toFixed(0), p99Ms: +(retraso.percentile(99) / 1e6).toFixed(0) };
    retraso.reset();
    return json(res, { ruta: 'retraso', ...r });
  }
  res.writeHead(404).end();
}).listen(PUERTO, '127.0.0.1', () => console.log(`pid ${process.pid} escuchando en ${PUERTO}`));

const { parentPort, workerData } = require('node:worker_threads');
const { fib } = require('./calculo.js');
parentPort.postMessage(fib(workerData));

const cluster = require('node:cluster');
const http = require('node:http');
const { fib } = require('./calculo.js');

const PUERTO = Number(process.env.PUERTO || 19085);
const PROCESOS = Number(process.env.PROCESOS || 2);

if (cluster.isPrimary) {
  console.log(`primario pid ${process.pid}, política de reparto: ${cluster.schedulingPolicy === cluster.SCHED_RR ? 'round-robin' : 'del sistema'}`);
  for (let i = 0; i < PROCESOS; i++) cluster.fork();
} else {
  http.createServer((req, res) => {
    const t0 = performance.now();
    const cuerpo = req.url === '/lenta' ? { ruta: 'lenta', resultado: fib(42) } : { ruta: 'rapida' };
    res.writeHead(200, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ pid: process.pid, ...cuerpo }));
  }).listen(PUERTO, '127.0.0.1');
}
